# POST /api/sheets/{sheetId}/periods/{periodName}/close — close a period (body: {user}), fixing its
# due-total and each person's due-total in it as they are now (the figures of the claims that count due by a date in it, skipping n/a); later rate
# changes do not alter it. Refused (400) when the sheet's permission matrix (perm-close; by default a
# clerk or a steward) does not allow the user's role, when the period is not on the sheet or is already closed;
# nothing is stored then. A soft-closed period may be closed, fixing its figures afresh. A closed period is recorded in the audit file as PERIOD_CLOSED.
validate:
  class: net.officefloor.hq.app.period.ValidateClose
  next: close
close:
  class: net.officefloor.hq.app.period.ClosePeriod
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.AuditPeriodClosed
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithClosedPeriod
  govern: [ transaction ]
# POST /api/sheets/{sheetId}/periods/{periodName}/soft-close — soft-close a period (body: {user}),
# fixing its due-total and each person's due-total in it as they are now, as a close does; claims dated
# inside it may still be added (marked late entries), edited, opened, settled and voided. It may later be
# closed (fixing the figures afresh) or reopened. Refused (400) as a close is: when the sheet's permission
# matrix (perm-close) does not allow the user's role, when the period is not on the sheet or is already
# closed or soft-closed; nothing is stored then. Recorded in the audit file as PERIOD_SOFT_CLOSED.
validate:
  class: net.officefloor.hq.app.period.ValidateClose
  next: close
close:
  class: net.officefloor.hq.app.period.SoftClosePeriod
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.AuditPeriodSoftClosed
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithClosedPeriod
  govern: [ transaction ]
# POST /api/sheets/{sheetId}/periods/{periodName}/reopen — reopen a closed or soft-closed period (body: {user}),
# dropping its fixed due-total so it totals its claims' current figures again. Refused (400) when the
# sheet's permission matrix (perm-reopen; by default a steward) does not allow the user's role, the period is not on the sheet or is neither closed nor soft-closed; nothing is
# stored then. A reopened period is recorded in the audit file as PERIOD_REOPENED.
validate:
  class: net.officefloor.hq.app.period.ValidateClose
  next: reopen
reopen:
  class: net.officefloor.hq.app.period.ReopenPeriod
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.AuditPeriodReopened
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithClosedPeriod
  govern: [ transaction ]
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Closes the period, fixing its due-total and each person's due-total in it as they are now: the figures of the claims whose due-by falls in
 *  it and that count by their status at its end, skipping n/a. Refused when the sheet's permission matrix does not allow the user's role to close (by default a clerk or a steward),
 *  there is no such period or it is already closed. */
public class ClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            @Val CloseRequest request, PeriodStore store, RoleStore roles, SettingStore settings, RollupService rollups,
            Out<PeriodResponse> closed) throws InvalidSheetException {
        String sheet = sheetId.trim();
        Role role = roles.find(sheet, request.user());
        if (!settings.allows(sheet, "close", role)) {
            throw new InvalidSheetException("A " + role.shown() + " may not close a period");
        }
        PeriodResponse period = store.find(sheet, periodName.trim());
        if (period == null) {
            throw new InvalidSheetException("No such period: " + periodName.trim());
        }
        if (period.closed()) {
            throw new InvalidSheetException("The period " + period.name() + " is already closed");
        }
